import json, sys
sys.path.insert(0, 'build')
from mm import *
K='referent.profile.protagonist.person.protagonist'; B='referent.profile.barbara.person.barbara'; L='referent.profile.laura.person.laura'
OLD='Old Swindon: the rented flat above a shop on Wood Street'; HART='White Hart House, the Hart\'s head office in west Swindon'; AVE='Avebury Trusloe and the Ridgeway, Wiltshire'; ONL='Online: the Sharehouse and the chains, every time zone'
E=[]; R=[]; C=[]
def add(eid, b, d, a, z, parent, part=None, reg=None, pids=None):
    E.append(event(eid, b, d, iv(a, z), part or {}, pids, reg)); R.append(rel(f'contains.{eid}', 'contains', parent, eid, 'Opened detail.'))
# states before decisions (inner)
add('ev.kieran.state.2022_01','Kieran\'s state in early January 2022, before the deposit moves.','The market is a third down from November; his seventy-one thousand is forty-five on the screen. House prices in Wroughton have risen faster than their deposit. His father has been out of work since July and pretends not to mind. The Sharehouse has spent December saying that the smart money is in safe yield now, twenty percent in a dollar that does not move. He believes he understands risk; what he feels is the old fear of being left behind and the new want to provide. He has not told Laura how much he has made or lost.',2022.0,2022.03,'ev.kieran.inner',{'subject':K},OLD,['kieran.stake_gbp','household.deposit_gbp'])
add('ev.laura.state.2022_01','Laura\'s state in early January 2022.','Four months out of the second wave and still sleeping badly. She wants to buy a house by the summer and has saved most of the deposit from overtime. She has not opened their savings app since the spring: Kieran is the one who knows about money, the way the monitors know about the patient. She is tired of being the one who holds everything.',2022.0,2022.03,'ev.laura.inner',{'subject':L},OLD,['household.deposit_gbp'])
add('ev.barbara.state.2022_02','Barbara\'s state in February 2022, when Kieran tells her where the deposit is.','She has walked with him most months for eighteen months and likes him more than she expected. She thinks everything that is not bitcoin is a casino and the stablecoin a confidence trick with a formula. She believes in adults choosing their own risks and has spent her life refusing to be anyone\'s mother. Under that, for the first time, is the thought that she gave him the key.',2022.1,2022.12,'ev.barbara.inner',{'subject':B},AVE)
add('ev.kieran.state.2022_05_09','Kieran\'s state on the evening of 9 May 2022, as the peg starts to slip.','Three hours of sleep a night since the weekend. The deposit is the only money he has that is not already down seventy percent. The Sharehouse is loud and sure: it has always come back, the founder is buying. What he knows about the mechanism depends on what Barbara told him in February. He has not told Laura where the deposit is, or has, depending on January. Leaving now would feel like leaving the band while it is losing.',2022.35,2022.353,'ev.kieran.inner',{'subject':K},OLD,['stablecoin.price_usd','household.deposit_gbp','kieran.sleep_hours'])
# Barbara's own decision
add('ev.barbara.stablecoin_walk','A Sunday in February 2022 on the Ridgeway: Kieran tells Barbara the deposit is in the stablecoin.','They walk from the car park above Avebury towards the long barrow. He tells her, pleased, about twenty percent in a dollar. She stops walking. What she does is drawn from cut.barbara.2022.response.',2022.12,2022.121,'event.profile.kieran_collapse.change_arc.anticipation',{'subject':B,'companion':K},AVE)
R.append(rel('barbara_state.enables.walk','enables','ev.barbara.state.2022_02','ev.barbara.stablecoin_walk','Her state is what she brings to the walk.'))
R.append(rel('deposit.enables.walk','enables','ev.kieran.deposit_move','ev.barbara.stablecoin_walk','The move is what he tells her.'))
R.append(rel('walk.enables.depeg','enables','ev.barbara.stablecoin_walk','ev.kieran.depeg_hold','What she told him is what he knows in May.'))
R.append(rel('kstate01.enables.deposit','enables','ev.kieran.state.2022_01','ev.kieran.deposit_move','His state before the move.'))
R.append(rel('lstate01.enables.deposit','enables','ev.laura.state.2022_01','ev.kieran.deposit_move','Her state before the move.'))
R.append(rel('kstate05.enables.depeg','enables','ev.kieran.state.2022_05_09','ev.kieran.depeg_hold','His state as the peg slips.'))
C.append(cut('cut.barbara.2022.response','ev.barbara.stablecoin_walk','What does Barbara do when Kieran tells her the deposit is in the stablecoin?','proposal weight over mutually exclusive continuations',[('warns_plainly_with_the_mechanism',0.35),('mocks_it_and_leaves_him_to_learn',0.30),('says_it_is_his_choice_and_nothing_more',0.25),('remainder',0.10)],'authored proposal weights from the modeled states, fixed before the estimate and draw'))
# opened adaptations
add('ev.kieran.game.no_trouble','2010-2012: Kieran becomes no trouble.','He learns the payments floor fast, volunteers for the early shift, never argues with a manager, and is praised for it. He stops seeing the guild; nobody on the floor knows he once ran forty people across Europe.',2010.35,2012.0,'event.profile.kieran_quits_game.change_arc.adaptation',{'subject':K},HART)
add('ev.kieran.rabbit.secret','November 2019 to March 2020: the card behind the bus pass.','He searches the words once on his phone and learns they are a recovery phrase; he does not type them in. The card makes the routine feel like a costume: every scam-check call now has a second voice in it. He does not tell Laura, the first thing in five years he has not told her.',2019.835,2020.195,'event.profile.kieran_white_rabbit.change_arc.adaptation',{'subject':K},HART)
add('ev.kieran.fall.sharehouse','June 2020: Kieran finds the Sharehouse.','A link in a forum thread about a food token leads to a chat server of a few thousand anonymous farmers awake in every time zone. They answer his questions at three in the morning and call him Kez after his wallet name. It is the first band that has needed him since the guild.',2020.45,2020.5,'event.profile.kieran_fall.change_arc.adaptation',{'subject':K},ONL,['sharehouse.members'])
add('ev.kieran.fall.first_stake','July 2020: six thousand pounds of his own savings go in.','His half of a holiday fund that the pandemic cancelled. He tells himself it is his money and not the deposit, which is true.',2020.52,2020.55,'event.profile.kieran_fall.change_arc.adaptation',{'subject':K},OLD,['kieran.stake_gbp'])
add('ev.kieran.fall.meets_barbara','September 2020: Kieran and Barbara meet in person and walk the Ridgeway.','She emails him from the address on her letter, which he answered in March with a single line. They meet in the car park above Avebury when people may meet outdoors in sixes. She is smaller than her voice and walks faster than he does.',2020.7,2020.71,'event.profile.kieran_fall.change_arc.adaptation',{'subject':K,'companion':B},AVE)
add('ev.kieran.father.rent','August to October 2021: Kieran pays his parents\' rent.','Three months of rent from his gains while his father looks for work at fifty-nine. His father thanks him once, in the car, without looking at him. It is the best thing the money does and it makes the money feel like proof.',2021.6,2021.8,'event.profile.kieran_father_plant.change_arc.adaptation',{'subject':K},'Penhill, Swindon',['kieran.stake_gbp'])
add('ev.barbara.retrain','1987-1988: Barbara retrains as a programmer.','A year of evening classes in COBOL at the technical college, paid for with her redundancy money; the only woman over thirty in the class; first in the exam.',1986.9,1988.5,'event.profile.barbara_works_closure.change_arc.adaptation',{'subject':B},'Swindon')
add('ev.barbara.reads_paper','2011: Barbara reads the bitcoin paper.','Nine pages that describe a ledger nobody can switch off. She reads it three times on the train to Reading and thinks: this is the part that waits, done properly.',2011.3,2011.4,'event.profile.barbara_crisis_2008.change_arc.adaptation',{'subject':B},'Reading, Berkshire')
add('ev.barbara.first_coins','2013: Barbara buys her first coins on retiring.','About a hundred dollars a coin; she keeps the keys on paper in a biscuit tin and never sells.',2013.2,2013.3,'event.profile.barbara_crisis_2008.change_arc.adaptation',{'subject':B},AVE)
add('ev.laura.move.boxes','2003-2009: Laura keeps her things in boxes.','In every room after the last move she keeps half her things packed. She decides at thirteen that she will own a front door nobody can take, and says so to nobody.',2003.6,2009.0,'event.profile.laura_last_move.change_arc.adaptation',{'subject':L},'Highworth, Wiltshire')
add('ev.laura.wave1.silence','Summer 2020: Laura stops telling Kieran about her shifts.','There are no words for the unit that do not frighten him, so she tells him about the car park and the canteen. He stops asking. Each of them is alone with a screen: hers the monitors, his the charts.',2020.4,2020.99,'event.profile.laura_first_wave.change_arc.adaptation',{'subject':L},'Old Swindon and the hospital')
add('ev.laura.wave2.car','Spring 2021: twenty minutes in the car, and the houses.','After the January wave she sits in the car outside the flat before coming up, and starts looking at houses in Wroughton on her phone there. The house becomes the one thing that is not the unit.',2021.15,2021.8,'event.profile.laura_second_wave.change_arc.adaptation',{'subject':L},'Old Swindon')
# causes for the shifts
add('ev.kieran.grandfather_dies','Spring 2001: Kieran\'s grandfather Ron dies.','Ron, a works fitter until 1986, dies at seventy-four of a stroke. Kieran, eleven, keeps his brass works tally token. After the funeral nobody talks about the works any more.',2001.3,2001.35,'ev.kieran.p1.childhood',{'subject':K},'Penhill, Swindon')
add('ev.car_plant.steady_2000s','2002-2008: the car plant\'s steady years.','Full shifts and overtime; his father stops worrying aloud about the plant until the 2009 recession.',2002.0,2008.9,'ev.car_plant.life',{},'South Marston, Swindon')
add('ev.barbara.apprenticeship_1969','September 1969: Barbara is let into the trade.','A new manager signs her on as an electrical apprentice after she beats every boy in the test; her father says nothing and gives her his screwdrivers.',1969.6,1969.7,'ev.barbara.p2.works',{'subject':B},'The railway works, Swindon')
add('ev.laura.leaves_home_2009','September 2009: Laura leaves home for nurse training.','A room in Oxford that is hers for three years; the first time she unpacks everything.',2009.7,2009.75,'ev.laura.p2.training',{'subject':L},'Oxford')
add('ev.laura.mother_settles_2012','2012: Laura\'s mother remarries and has a secure home.','A council transfer and a kind second husband; Laura stops worrying about her mother\'s roof.',2012.3,2012.4,'ev.laura.p2.training',{'subject':L},'Highworth, Wiltshire')
R += [rel('grandfather.causes.p2','causes','ev.kieran.grandfather_dies','ev.kieran.p2.game','After Ron\'s death the works are not spoken of; the game fills the house\'s silence.'),
 rel('steady.causes.p2','causes','ev.car_plant.steady_2000s','ev.kieran.p2.game','Steady shifts stop the family worrying about work until 2009.'),
 rel('apprentice.causes.works','causes','ev.barbara.apprenticeship_1969','ev.barbara.p2.works','Being let in ends the threat of being kept out.'),
 rel('closure.causes.bureau','causes','event.profile.barbara_works_closure.change_arc.focal_change','ev.barbara.p3.bureau','The closure ends her place in the shop and starts the bureau years.'),
 rel('crisis.causes.retirement_threat','causes','event.profile.barbara_crisis_2008.change_arc.focal_change','ev.barbara.p4.retirement','After 2008 her savings in the old system feel threatened.'),
 rel('exit.causes.story_period','causes','event.profile.barbara_exit_2019.change_arc.focal_change','ev.barbara.p5.story','Once her savings are out, the old system cannot threaten them.'),
 rel('leaves_home.causes.training','causes','ev.laura.leaves_home_2009','ev.laura.p2.training','A room of her own ends the fear for the house.'),
 rel('mother.causes.nursing','causes','ev.laura.mother_settles_2012','ev.laura.p3.nursing','Her mother is safe, so her mother is no longer what is threatened.'),
 rel('wave1.causes.pandemic_period','causes','event.profile.laura_first_wave.change_arc.focal_change','ev.laura.p4.pandemic','The first wave takes her assurance and replaces the deposit worry with her patients.')]
# Things opened
add('ev.hart.block_decision_2021','June 2021: the Hart decides to block payments to several crypto exchanges.','After regulator warnings and a run of scam losses the board blocks card and bank payments to several exchanges. Kieran, who knows why payments fail, is seconded to the project that builds the block.',2021.44,2021.46,'ev.hart.life',{'institution':'referent.hart','staff':K},HART)
add('ev.hart.fraud_week_2022','The week of 9 May 2022 at the Hart: the fraud lines fill.','Customers who moved savings into crypto, some through the very workarounds Kieran used, call about money that is gone. Staff from payments are pulled onto the phones.',2022.353,2022.37,'ev.hart.life',{'institution':'referent.hart','staff':K},HART)
add('ev.clearing.batch_night','A typical clearing cycle at the Hart.','The outgoing file is built at ten at night and submitted; overnight the scheme processes it; at seven the exceptions queue shows what failed and why: a closed account, a mismatched name, a fraud flag. Nothing moves at weekends. The failure mode is a file that does not arrive and a day of payments that wait.',2019.8,2023.25,'ev.clearing.life',{},HART,['clearing.cycle_days'])
add('ev.sharehouse.founding','Spring 2020: the Sharehouse is founded.','A dozen yield farmers start a chat server as lockdown begins; by summer it has a few thousand members, channels named after food tokens, and a rule that nobody asks anybody\'s real name.',2020.3,2020.45,'ev.sharehouse.life',{},ONL,['sharehouse.members'])
add('ev.sharehouse.panic_2022','9 to 13 May 2022 in the Sharehouse.','First certainty (it always comes back), then instructions (do not sell, that is what they want), then silence, then jokes, then goodbyes. By the end of May half the channels are empty.',2022.353,2022.4,'ev.sharehouse.life',{},ONL,['sharehouse.members'])
add('ev.card.behind_bus_pass','November 2019 to March 2020: the card behind the bus pass.','The white card rides in Kieran\'s wallet every day behind his bus pass, soft at the corners by March.',2019.835,2020.195,'ev.card.life',{},HART,['card.wallet_btc'])
add('ev.stablecoin.mechanism','How the stablecoin worked, 2020-2022.','Parts: the dollar token; the sister token; a swap that always let anyone trade one dollar token for a dollar\'s worth of the sister token and back; a savings protocol paying about twenty percent from reserves and new deposits. Capacity: the peg held while the sister token was worth more than the dollar tokens outstanding. Failure mode: when enough holders swapped at once, new sister tokens were minted, its price fell, each swap needed more of them, and the fall fed itself.',2020.7,2022.35,'ev.stablecoin.life',{},ONL,['stablecoin.price_usd'])
add('ev.stablecoin.spiral','9 to 13 May 2022: the spiral.','Withdrawals from the savings protocol and large sales push the token below a dollar; swaps mint the sister token by the billion; within four days the sister token is worth almost nothing and the stablecoin trades for cents.',2022.353,2022.364,'ev.stablecoin.life',{},ONL,['stablecoin.price_usd'])
add('ev.car_plant.last_car','30 July 2021: the last car leaves the line.','Kieran\'s father works the final shift, brings home his hi-vis vest and a commemorative mug, and puts the mug in a cupboard.',2021.57,2021.58,'ev.car_plant.life',{},'South Marston, Swindon')
add('ev.works.hooter','The works hooter as the town\'s clock, 1843-1986.','For a hundred and forty years the hooter sounded the shifts across the town; people who never worked in the works set their clocks by it.',1843,1986.25,'ev.works.life',{},'Swindon')
add('ev.stones.raising','About 2600 BC: the stones are dragged into place.','Farming communities drag sarsen stones of up to forty tons across the downs on sledges and rollers over generations, to make a place to gather at set seasons.',-2650,-2550,'ev.stones.life',{},'Avebury, Wiltshire')
add('ev.flat.fridge_rota','The rota on the fridge.','Laura\'s shift pattern printed each month and held to the fridge by a magnet from Weymouth; it tells Kieran when she will be asleep, awake or gone.',2016.3,2023.25,'ev.flat.life',{},OLD)
